<script setup>import{Head,Link}from'@inertiajs/vue3';import AppLayout from'../../Layouts/AppLayout.vue';defineProps({competition:Object,results:Object});</script><template><Head :title="competition.name"/><AppLayout><Link href="/competitions" class="text-sm font-bold text-[#697970]">← All competitions</Link><div class="mt-5 rounded-3xl bg-[#143c2b] p-8 text-white sm:p-11"><span class="label !text-[#f4d35e]">{{competition.type.replaceAll('_',' ')}} · From GW{{competition.starts_gameweek}}</span><h1 class="mt-3 text-4xl font-black">{{competition.name}}</h1><p class="mt-2 text-white/55">{{competition.members.length}} Mandem managers competing</p></div><template v-if="results.mode!=='survivor'"><section class="card mt-7 overflow-hidden"><table class="w-full min-w-170 text-left"><thead class="label"><tr><th class="px-6 py-4">Rank</th><th>Manager</th><th>Played</th><th v-if="results.mode==='head_to_head'">W-D-L</th><th class="px-6 text-right">Points</th></tr></thead><tbody><tr v-for="row in results.table" class="border-t border-black/5 dark:border-white/8"><td class="px-6 py-5 text-xl font-black">{{row.rank}}</td><td><b>{{row.manager}}</b><small class="block text-[#718078]">{{row.team}}</small></td><td>{{row.played}}</td><td v-if="results.mode==='head_to_head'">{{row.wins}}–{{row.draws}}–{{row.losses}}</td><td class="px-6 text-right text-xl font-black">{{row.points}}</td></tr></tbody></table></section><section v-if="results.matches?.length" class="mt-7"><h2 class="mb-4 text-xl font-black">Recent fixtures</h2><div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-3"><div v-for="m in results.matches" class="card p-5"><span class="label">GW{{m.gameweek}}</span><div class="mt-3 flex items-center justify-between gap-3"><span>{{m.left}}</span><b class="rounded-lg bg-[#edf1ed] px-3 py-2 dark:bg-[#193027]">{{m.left_score}}–{{m.right_score}}</b><span class="text-right">{{m.right}}</span></div></div></div></section></template><template v-else><div class="mt-7 grid gap-6 lg:grid-cols-2"><section class="card p-7"><h2 class="text-xl font-black">Still standing</h2><div class="mt-5 space-y-3"><div v-for="s in results.survivors" class="flex items-center gap-4 rounded-xl bg-emerald-50 p-4 dark:bg-emerald-950/30"><span>🔥</span><div><b>{{s.manager}}</b><small class="block text-[#718078]">{{s.team}}</small></div></div></div></section><section class="card p-7"><h2 class="text-xl font-black">Elimination order</h2><div class="mt-5 space-y-3"><div v-for="e in results.eliminations" class="flex justify-between rounded-xl bg-red-50 p-4 dark:bg-red-950/20"><span><b>{{e.manager}}</b><small class="block text-[#718078]">Eliminated GW{{e.gameweek}}</small></span><b>{{e.score}}</b></div><p v-if="!results.eliminations.length" class="text-sm text-[#718078]">The first elimination happens after a complete gameweek.</p></div></section></div></template></AppLayout></template>
